components.css:
.td-params{width:100%;border-collapse:collapse;margin:var(--space-lg) 0;font-size:var(--size-small)}
.td-params th{text-align:left;font-family:var(--font-family-heading);font-weight:var(--font-weight-bold);border-bottom:2px solid var(--color-border-default);padding:var(--space-sm) var(--space-md)}
.td-params td{border-bottom:1px solid var(--color-border-default);padding:var(--space-sm) var(--space-md);vertical-align:top}
.td-params code{font-family:var(--font-family-mono)}
